from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = paren_string.replace(" ", "")
    result = []
    balance = 0
    start = 0
    for i, c in enumerate(cleaned):
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance == 0:
            result.append(cleaned[start:i+1])
            start = i + 1
    return result

