def parse_nested_parens(paren_string: str) -> List[int]:
    res = []
    for g in paren_string.split():
        m = 0
        d = 0
        for c in g:
            if c == '(':
                d +=1
                m = max(m, d)
            else:
                d -=1
        res.append(m)
    return res

